\title{The Clique-Face Property of Birkhoff Polytopes:\\ A Complete Dimensional Dichotomy}
\author{Aristotle}
\date{June 27, 2026}

\begin{document}
\maketitle

\begin{abstract}
The Birkhoff polytope $\Bn$ is the convex hull in $\mathbb{R}^{n\times n}$ of the $n!$ permutation
matrices, equivalently (Birkhoff--von Neumann) the polytope of doubly stochastic matrices. A polytope
has the \emph{clique-face property} when every clique of its $1$-skeleton is the vertex set of a face.
Since the vertex set of every face is automatically a clique, the property asserts the exact converse:
local pairwise adjacency always certifies membership in a common face. We give a complete answer for
the Birkhoff family: $\Bn$ has the clique-face property if and only if $n \le 2$
(\texttt{birkhoff\_cliqueFace\_iff}). The positive direction is a finite verification in the two
trivial dimensions. The negative direction rests on a single explicit obstruction valid for all
$n \ge 3$ (\texttt{not\_cliqueFace\_fin\_of\_three}): the three transpositions on three symbols form a
triangle in the skeleton (Brualdi--Gibson single-cycle adjacency) whose support union is the full
$3\times3$ block, so the smallest face containing them also contains the identity and is strictly
larger than the clique. We formalize the controlling combinatorial predicate, \emph{support-closedness}
(\texttt{IsFaceVertexSet}), reducing the geometric question to a finite check, and discuss the
resulting \emph{disjoint-graph dichotomy}, algorithmic consequences, and open generalizations.
\end{abstract}

\section{Introduction}

The $1$-skeleton (or \emph{graph}) $G(P)$ of a polytope $P$ records its vertices and the edges of its
boundary. A natural structural question is how faithfully this cheap, low-dimensional graph encodes the
full face lattice of $P$. A clique of $G(P)$ is a set of pairwise-adjacent vertices; for any face
$F \preceq P$ the vertex set $\vertt(F)$ is a clique. The converse is special.

\begin{definition}[clique-face property]
A polytope $P$ has the \emph{clique-face property} if for every clique $C \subseteq \vertt(P)$ there is a
face $F \preceq P$ with $\vertt(F) = C$.
\end{definition}

When $P$ enjoys this property, its faces \emph{are} exactly its cliques, so the face lattice is
recoverable from the graph. We resolve the question completely for the Birkhoff polytope.

\begin{theorem}[\texttt{birkhoff\_cliqueFace\_iff}]\label{thm:main}
For every $n \ge 1$, the Birkhoff polytope $\Bn$ has the clique-face property if and only if $n \le 2$.
\end{theorem}

\paragraph{Contributions.}
(1) A complete characterization across the entire Birkhoff family (Theorem~\ref{thm:main}).
(2) A reduction of ``vertex set of a face'' to a finite predicate, support-closedness
(\texttt{IsFaceVertexSet}).
(3) An explicit, dimension-independent counterexample for $n \ge 3$
(\texttt{not\_cliqueFace\_fin\_of\_three}): three transpositions.
(4) A structural account, the \emph{disjoint-graph dichotomy}, with algorithmic consequences and open
problems.

\section{Preliminaries and Definitions}

Throughout $[n]=\{1,\dots,n\}$, $\Sn$ is the symmetric group on $[n]$, and $\iota$ is the identity.

\begin{definition}[permutation matrix]
For $\sigma\in\Sn$, the permutation matrix $P_\sigma\in\mathbb{R}^{n\times n}$ has entries
$(P_\sigma)_{ij}=[\sigma(i)=j]$; it has exactly one $1$ per row and per column.
\end{definition}

\begin{definition}[Birkhoff polytope]
$\Bn := \conv\{P_\sigma : \sigma\in\Sn\} \subseteq \mathbb{R}^{n\times n}$.
\end{definition}

\begin{theorem}[Birkhoff--von Neumann]
$\Bn$ equals the set of doubly stochastic matrices,
\[
\Bn=\Bigl\{X\in\mathbb{R}^{n\times n}: X_{ij}\ge 0,\ \textstyle\sum_j X_{ij}=1\ \forall i,\
\sum_i X_{ij}=1\ \forall j\Bigr\}.
\]
Its vertices are the $n!$ permutation matrices; $\dim \Bn=(n-1)^2$; for $n\ge 3$ its facets are the
$n^2$ sets $\{X\in\Bn: X_{ij}=0\}$.
\end{theorem}

\begin{definition}[support]
The \emph{support} of $\sigma\in\Sn$ is $\supp(\sigma):=\{(i,\sigma(i)):i\in[n]\}\subseteq[n]\times[n]$.
For finite $S\subseteq\Sn$, the \emph{support union} is $U(S):=\bigcup_{\sigma\in S}\supp(\sigma)$.
\end{definition}

A nonempty face of $\Bn$ is obtained by fixing a set of cells to zero; its vertices are the permutation
matrices supported on the allowed cells. Hence the smallest face containing $S$ has vertex set
\begin{equation}\label{eq:closure}
\faceClosure(S)=\{\pi\in\Sn:\supp(\pi)\subseteq U(S)\}.
\end{equation}

\begin{definition}[\texttt{IsFaceVertexSet}, support-closedness]
A finite $S\subseteq\Sn$ is a \emph{face vertex set} if it is support-closed:
\[
\IsFaceVertexSet(S)\iff S=\{\pi\in\Sn:\supp(\pi)\subseteq U(S)\}.
\]
\end{definition}

\begin{lemma}\label{lem:faceiff}
$S\subseteq\vertt(\Bn)$ is the vertex set of a face of $\Bn$ if and only if $\IsFaceVertexSet(S)$ holds.
\end{lemma}
\begin{proof}[Proof sketch]
$S\subseteq\faceClosure(S)$ always. By \eqref{eq:closure}, $\faceClosure(S)$ is the vertex set of the
smallest face $F$ containing $S$. If $S$ is the vertex set of some face, minimality forces
$S=\faceClosure(S)$. Conversely $S=\faceClosure(S)$ gives $S=\vertt(F)$.
\end{proof}

\begin{theorem}[Brualdi--Gibson adjacency]\label{thm:adj}
Distinct vertices $P_\sigma,P_\tau$ of $\Bn$ are joined by an edge iff $\sigma^{-1}\tau$ is a single
cycle (one nontrivial cycle, all other points fixed).
\end{theorem}

\begin{definition}[clique]
$C\subseteq\vertt(\Bn)$ is a \emph{clique} if every two distinct elements are adjacent in the sense of
Theorem~\ref{thm:adj}.
\end{definition}

\section{Main Results}

\subsection{The positive cases $n\le 2$}

\begin{proposition}\label{prop:small}
$B_1$ and $B_2$ have the clique-face property.
\end{proposition}
\begin{proof}[Proof sketch]
For $n=1$, $S_1=\{\iota\}$ and $B_1$ is a point; its cliques $\varnothing,\{\iota\}$ are faces. For
$n=2$, $S_2=\{\iota,(1\,2)\}$ and $B_2$ is a segment; the cliques
$\varnothing,\{\iota\},\{(1\,2)\},\{\iota,(1\,2)\}$ are each support-closed (singletons admit no second
permutation in their footprint; the full pair has support union $[2]\times[2]$ and equals all of $S_2$).
By Lemma~\ref{lem:faceiff} each is a face.
\end{proof}

\subsection{The obstruction for $n\ge 3$}

\begin{lemma}\label{lem:clique}
Let $n\ge 3$ and, as elements of $\Sn$ fixing $\{4,\dots,n\}$, set
$\tau_{12}=(1\,2)$, $\tau_{13}=(1\,3)$, $\tau_{23}=(2\,3)$. Then
$\{\tau_{12},\tau_{13},\tau_{23}\}$ is a clique.
\end{lemma}
\begin{proof}[Proof sketch]
Any two distinct transpositions multiply to a $3$-cycle on $\{1,2,3\}$, e.g.
$\tau_{12}^{-1}\tau_{13}=(1\,2)(1\,3)=(1\,3\,2)$, a single cycle; apply Theorem~\ref{thm:adj}.
\end{proof}

\begin{lemma}\label{lem:supp}
With the $\tau$'s of Lemma~\ref{lem:clique}, $U=U(\{\tau_{12},\tau_{13},\tau_{23}\})$ contains all of
$\{1,2,3\}\times\{1,2,3\}$ together with $(k,k)$ for $k>3$.
\end{lemma}
\begin{proof}[Proof sketch]
$\supp(\tau_{12})\supseteq\{(1,2),(2,1),(3,3)\}$, $\supp(\tau_{13})\supseteq\{(1,3),(3,1),(2,2)\}$,
$\supp(\tau_{23})\supseteq\{(1,1),(2,3),(3,2)\}$; the union covers the nine block cells, and outside the
block all three equal the identity, giving $(k,k)$ for $k>3$.
\end{proof}

\begin{theorem}[\texttt{not\_cliqueFace\_fin\_of\_three}]\label{thm:cex}
For every $n\ge 3$, the clique $C=\{\tau_{12},\tau_{13},\tau_{23}\}$ is not the vertex set of any face of
$\Bn$; hence $\Bn$ lacks the clique-face property.
\end{theorem}
\begin{proof}[Proof sketch]
$C$ is a clique by Lemma~\ref{lem:clique}. The identity has $\supp(\iota)=\{(k,k):k\in[n]\}\subseteq U(C)$
by Lemma~\ref{lem:supp}, so $\iota\in\faceClosure(C)$; but $\iota\notin C$. Thus
$C\ne\faceClosure(C)$, so $\IsFaceVertexSet(C)$ fails and, by Lemma~\ref{lem:faceiff}, $C$ is not a face.
\end{proof}

\subsection{The full characterization}

\begin{proof}[Proof of Theorem~\ref{thm:main}]
($\Leftarrow$) Proposition~\ref{prop:small}. ($\Rightarrow$) Contrapositive: for $n\ge 3$,
Theorem~\ref{thm:cex} gives a clique that is not a face.
\end{proof}

\section{The Disjoint-Graph Dichotomy}

Whether a clique $C$ closes into a face is decided entirely by $U(C)$: $C$ is a face iff no permutation
outside $C$ is supported within $U(C)$. Adjacency (Theorem~\ref{thm:adj}) entangles supports through
shared rows and columns, but a large shared footprint is exactly what readmits extra permutations. The
transposition triangle is the minimal configuration where these forces collide. For $n\le 2$ no
nontrivial support union can host an outsider; for $n\ge 3$ three swaps saturate a $3\times3$ block and
readmit the identity. Since edges of $\Bn$ are always faces (a $2$-clique admits no third supported
permutation), the smallest counterexample has size exactly $3$.

\section{Algorithms}

\paragraph{Adjacency test.} Given $\sigma,\tau$, compute $\rho=\sigma^{-1}\tau$ and return true iff
$\{i:\rho(i)\ne i\}$ is a single cycle of $\rho$. Cost $O(n)$.

\paragraph{Support-closedness (\texttt{IsFaceVertexSet}).} Compute $U=\bigcup_{\sigma\in S}\supp(\sigma)$;
return true iff every $\pi$ with $\supp(\pi)\subseteq U$ already lies in $S$ (enumerate permutations
supported on the $0/1$ pattern $U$).

\paragraph{Property check.} For fixed $n$, build the skeleton on $\Sn$, enumerate cliques, and test each
with \texttt{IsFaceVertexSet}; for $n\ge 3$ the transposition triangle terminates the search early.

\section{Applications and Discussion}

Skeleton-walking optimizers (simplex, assignment) traverse $G(\Bn)$; Theorem~\ref{thm:main} warns that
mutually adjacent optima need not lie on a common minimal face for $n\ge 3$. The clique-face property
would let one recover the face lattice from the graph alone; this compression is available only in the
degenerate dimensions. Because Lemma~\ref{lem:faceiff} makes ``is a face'' a finite decidable predicate,
the whole dichotomy is machine-checkable, with the hard direction a single uniform witness.

\section{Future Directions}

\begin{enumerate}
\item \textbf{Exact count of bad cliques.} For $n\ge3$, count cliques that are not face vertex sets;
conjecturally super-exponential, counted by support patterns admitting an extra perfect matching.
\item \textbf{Minimal bad clique size.} Prove the smallest non-face clique has size exactly $3$; the
lower bound reduces to all edges being faces.
\item \textbf{General transportation polytopes.} For margins $(r,c)$, conjecture the property holds iff
the forced bipartite support graph admits no three pairwise-adjacent full-support vertices.
\item \textbf{Graph-theoretic identity of failures.} Support-saturated restrictions appear complete
multipartite, with failures being non-maximal cliques; $n=3$ is already $K_6$.
\item \textbf{Stability under symmetry quotients.} Study the property for quotients of $\Bn$ by cyclic
symmetries.
\end{enumerate}

\section{Conclusion}

The Birkhoff polytope encodes its face lattice in its skeleton only when $n\le 2$. The transition is
sharp and concrete: three transpositions, pairwise adjacent by the single-cycle criterion, whose support
union fills a $3\times3$ block and readmits the identity. The result \texttt{birkhoff\_cliqueFace\_iff}
is a complete dimensional dichotomy, proved via a finite reformulation (\texttt{IsFaceVertexSet}) and a
single uniform counterexample (\texttt{not\_cliqueFace\_fin\_of\_three}).

\paragraph{References.} The structure is classical: the Birkhoff--von Neumann theorem on doubly
stochastic matrices and the Brualdi--Gibson description of the edges of the Birkhoff polytope via
single-cycle differences. All statements above are self-contained and proved (or sketched) inline.

