from typing import FrozenSet, List, Set, Tuple
Perm = Tuple[int, ...]
Cell = Tuple[int, int]

def compose(a: Perm, b: Perm) -> Perm:
    return tuple(a[b[i]] for i in range(len(a)))

def inverse(p: Perm) -> Perm:
    inv = [0] * len(p); 
    for i, v in enumerate(p): inv[v] = i
    return tuple(inv)

def is_single_cycle(p: Perm) -> bool:
    seen = [False] * len(p); cnt = 0
    for s in range(len(p)):
        if seen[s]: continue
        length = 0; j = s
        while not seen[j]:
            seen[j] = True; j = p[j]; length += 1
        if length >= 2: cnt += 1
    return cnt == 1

def adjacent(a: Perm, b: Perm) -> bool:
    return a != b and is_single_cycle(compose(inverse(a), b))

def support(p: Perm) -> FrozenSet[Cell]:
    return frozenset((i, p[i]) for i in range(len(p)))

def demo_three_transpositions(n: int = 3) -> None:
    """Exhibit the size-3 counterexample not_cliqueFace_fin_of_three."""
    t12 = tuple([1, 0] + list(range(2, n)))
    t13 = tuple([2, 1, 0] + list(range(3, n)))
    t23 = tuple([0, 2, 1] + list(range(3, n)))
    clique = [t12, t13, t23]
    u: Set[Cell] = set()
    for p in clique: u |= support(p)
    idn = tuple(range(n))
    print("pairwise adjacent (clique):", all(adjacent(a, b) for a, b in combinations(clique, 2)))
    print("support union fills 3x3 block:", all((i, j) in u for i in range(3) for j in range(3)))
    print("identity supported inside union:", support(idn) <= u)
    print("=> clique is NOT a face: identity is an extra enclosed vertex")

if __name__ == "__main__":
    demo_three_transpositions(3)

